 function demo(){if(preparing||audioUploading)return;setShowExercises(false);setPdfAnswerHints([]);setWordBankHints([]);setPdfPages([]);setOriginalFile(null);setShowOriginal(false);setPdfPageIndex(0);if(sourceMode==='unsolved'){setText('Complete with the present simple.\n\n1. She ____ to school every day. (go)\n2. They ____ football on Sundays. (play)\n\nAnswer the question.\n\n3. What is the past tense of eat?');setMarks([]);setAiParts([]);setAiWarnings([]);setAiReviewed(false);setTitle('English practice · AI edition');setFilename('Ejemplo sin resolver');setStep(2);setPage('create');setPublished('');setAnswers({});return;}setAiParts([]);setText(example);const m=sampleAnswers.map((answer,i)=>{const sentence=example.indexOf(`${i+1}.`);const start=example.indexOf(answer,sentence);return {start,end:start+answer.length,id:crypto.randomUUID()}});setMarks(m);setTitle('Everyday English · Unit 3');setFilename('Ejemplo de examen');setStep(2);setPage('create');setPublished('');setAnswers({});setNotice('Ejemplo cargado: 6 respuestas marcadas. Podés modificarlas.');}
