 <div className="page-heading"><div><div className="eyebrow">HELLO, TEACHER 👋</div><h1>{page==='create'?'Un buen examen empieza acá.':page==='exams'?'Todo listo para tu próxima clase.':'Exámenes entregados.'}</h1><p>{page==='create'?'Tus PDFs, con o sin respuestas, se convierten en exámenes para aprender.':page==='exams'?'Tus exámenes preparados, en un solo lugar.':'Buscá por nombre o curso y revisá el examen de cada alumno.'}</p></div>{page!=='create'&&<button className="primary" onClick={newDraft}><Plus size={17}/>Nuevo examen</button>}</div>
